create or replace function public.planner_links_same_owner() returns trigger language plpgsql security definer set search_path = public as $$ declare v_project_owner uuid; v_status_owner uuid; begin select user_id into v_project_owner from public.gap_projects where id = new.project_id; if v_project_owner is distinct from new.user_id then raise exception 'A planner link must belong to its own project'; end if; select user_id into v_status_owner from public.planner_statuses where id = new.status_id; if v_status_owner is distinct from new.user_id then raise exception 'A planner link must use one of its owner''s statuses'; end if; return new; end; $$;
