create or replace function public.planner_seed_statuses(p_user_id uuid) returns integer language plpgsql security definer set search_path = public as $$ declare v_existing integer; begin select count(*) into v_existing from public.planner_statuses where user_id = p_user_id; if v_existing > 0 then return 0; end if; insert into public.planner_statuses (user_id, name, colour, category, sort_order) values (p_user_id, 'Planned', '#64748b', 'planned', 10), (p_user_id, 'Outreach Sent', '#64748b', 'in_progress', 20), (p_user_id, 'Awaiting Response', '#64748b', 'in_progress', 30), (p_user_id, 'Approved', '#2563eb', 'in_progress', 40), (p_user_id, 'Ordered', '#2563eb', 'in_progress', 50), (p_user_id, 'In Progress', '#2563eb', 'in_progress', 60), (p_user_id, 'Scheduled', '#7c3aed', 'scheduled', 70), (p_user_id, 'Waiting to Go Live','#d97706', 'waiting', 80), (p_user_id, 'Live', '#059669', 'live', 90), (p_user_id, 'Lost', '#dc2626', 'lost', 100), (p_user_id, 'Cancelled', '#8595a6', 'cancelled', 110); return 11; end; $$;
